#include "FxChain.h"
#include <cmath>
#include <limits>
namespace stage {
int FxChain::count()const{int n=0;for(auto& node:nodes)n+=node.plugin!=nullptr;return n;}
int FxChain::latencySamples()const{int64_t latency=0;for(auto& node:nodes)if(node.plugin&&!node.bypassed)latency+=juce::jmax(0,node.plugin->getLatencySamples());return (int)juce::jmin(latency,(int64_t)std::numeric_limits<int>::max());}
juce::String FxChain::configureStereo(juce::AudioPluginInstance& plugin){
    juce::PluginDescription description;plugin.fillInPluginDescription(description);
    if(description.isInstrument||plugin.isMidiEffect()||plugin.getBusCount(true)<1||plugin.getBusCount(false)<1)
        return juce::String::fromUTF8("FXにはステレオ音声の入力と出力があるエフェクトを選んでください。音源は音源枠へ追加します。");
    auto layout=plugin.getBusesLayout();for(auto& bus:layout.inputBuses)bus=juce::AudioChannelSet::disabled();for(auto& bus:layout.outputBuses)bus=juce::AudioChannelSet::disabled();
    layout.inputBuses.getReference(0)=juce::AudioChannelSet::stereo();layout.outputBuses.getReference(0)=juce::AudioChannelSet::stereo();
    if(!plugin.checkBusesLayoutSupported(layout)||!plugin.setBusesLayout(layout)||plugin.getTotalNumInputChannels()!=2||plugin.getTotalNumOutputChannels()!=2)
        return juce::String::fromUTF8("このFXはステレオ入出力に対応していません。外部サイドチェインや多チャンネル専用のFXは使えません。");
    plugin.setNonRealtime(false);return {};
}
void FxChain::prepare(double sr,int n){sampleRate=sr;blockSize=n;if(count()>0)midi.ensureSize(65536);midi.clear();for(auto& node:nodes)if(node.plugin){node.plugin->setRateAndBufferSizeDetails(sr,n);node.plugin->prepareToPlay(sr,n);}}
void FxChain::release(){for(auto& node:nodes)if(node.plugin)node.plugin->releaseResources();midi.clear();}
void FxChain::reset(){for(auto& node:nodes)if(node.plugin)node.plugin->reset();midi.clear();}
void FxChain::process(juce::AudioBuffer<float>& buffer){
    if(buffer.getNumSamples()<=0||buffer.getNumChannels()<2||buffer.getNumSamples()>blockSize)return;
    // A non-owning two-channel view uses JUCE's fixed channel-pointer storage.
    juce::AudioBuffer<float> stereo(buffer.getArrayOfWritePointers(),2,buffer.getNumSamples());
    for(auto& node:nodes)if(node.plugin&&!node.bypassed.load(std::memory_order_relaxed)){
        midi.clear();node.plugin->processBlock(stereo,midi);
        // Do not feed MIDI generated by one FX into another or into the instruments.
        for(int ch=0;ch<2;++ch){auto* samples=stereo.getWritePointer(ch);for(int n=0;n<stereo.getNumSamples();++n)if(!std::isfinite(samples[n]))samples[n]=0;}
    }midi.clear();
}
void FxChain::clear(){release();for(auto& node:nodes)node=FxNode{};}
void FxChain::remove(int index){if(index<0||index>=fxCapacity)return;if(nodes[(size_t)index].plugin)nodes[(size_t)index].plugin->releaseResources();for(int n=index;n<fxCapacity-1;++n)nodes[(size_t)n]=std::move(nodes[(size_t)n+1]);nodes.back()=FxNode{};}
void FxChain::moveNode(int from,int to){if(from<0||from>=fxCapacity||to<0||to>=fxCapacity||from==to)return;auto moving=std::move(nodes[(size_t)from]);if(from<to)for(int n=from;n<to;++n)nodes[(size_t)n]=std::move(nodes[(size_t)n+1]);else for(int n=from;n>to;--n)nodes[(size_t)n]=std::move(nodes[(size_t)n-1]);nodes[(size_t)to]=std::move(moving);}
void FxChain::swapWith(FxChain& other){for(int n=0;n<fxCapacity;++n){auto temp=std::move(nodes[(size_t)n]);nodes[(size_t)n]=std::move(other.nodes[(size_t)n]);other.nodes[(size_t)n]=std::move(temp);}std::swap(sampleRate,other.sampleRate);std::swap(blockSize,other.blockSize);midi.clear();other.midi.clear();}

class GateParameter final:public juce::HostedAudioProcessorParameter{
    juce::String id,name;float initial;std::atomic<float> value;
public:
    GateParameter(juce::String key,juce::String title,float v):id(key),name(title),initial(v),value(v){}
    juce::String getParameterID()const override{return id;}juce::String getName(int n)const override{return name.substring(0,n);}juce::String getLabel()const override{return id=="threshold"?"dB":"%";}
    float getValue()const override{return value;}float getDefaultValue()const override{return initial;}void setValue(float v)override{value=juce::jlimit(0.0f,1.0f,v);}
    juce::String getText(float v,int)const override{return juce::String(id=="threshold"?juce::Decibels::gainToDecibels(v*.25f,-100.0f):v*100.0f,1);}float getValueForText(const juce::String& t)const override{return juce::jlimit(0.0f,1.0f,id=="threshold"?juce::Decibels::decibelsToGain(t.getFloatValue(),-100.0f)/.25f:t.getFloatValue()/100.0f);}
};
class GateFx final:public juce::AudioPluginInstance{
    GateParameter *threshold,*gain;double envelope=0;float gate=0;double smoothing=.999;
public:
    GateFx():AudioPluginInstance(BusesProperties().withInput("Stereo",juce::AudioChannelSet::stereo(),true).withOutput("Stereo",juce::AudioChannelSet::stereo(),true)){
        auto t=std::make_unique<GateParameter>("threshold",juce::String::fromUTF8("ゲートのしきい値"),.02f);threshold=t.get();addHostedParameter(std::move(t));auto g=std::make_unique<GateParameter>("gain",juce::String::fromUTF8("出力音量"),1);gain=g.get();addHostedParameter(std::move(g));
    }
    const juce::String getName()const override{return juce::String::fromUTF8("内蔵ノイズゲート");}
    void fillInPluginDescription(juce::PluginDescription& d)const override{d.name=getName();d.pluginFormatName="Internal";d.fileOrIdentifier="stage:gate";d.isInstrument=false;d.numInputChannels=2;d.numOutputChannels=2;}
    bool isBusesLayoutSupported(const BusesLayout& layout)const override{return layout.getMainInputChannelSet()==juce::AudioChannelSet::stereo()&&layout.getMainOutputChannelSet()==juce::AudioChannelSet::stereo();}
    void prepareToPlay(double sr,int n)override{setRateAndBufferSizeDetails(sr,n);smoothing=std::exp(-1.0/(sr*.02));reset();}void releaseResources()override{}void reset()override{envelope=0;gate=0;}
    void processBlock(juce::AudioBuffer<float>& b,juce::MidiBuffer&)override{float limit=threshold->getValue()*.25f,level=gain->getValue();float attack=(float)(1-std::exp(-1.0/(getSampleRate()*.002))),release=(float)(1-std::exp(-1.0/(getSampleRate()*.015)));for(int n=0;n<b.getNumSamples();++n){float input=juce::jmax(std::abs(b.getSample(0,n)),std::abs(b.getSample(1,n)));envelope=juce::jmax((double)input,envelope*smoothing);float target=envelope>=limit?1.0f:0.0f;gate+=(target-gate)*(target>gate?attack:release);for(int ch=0;ch<b.getNumChannels();++ch)b.setSample(ch,n,b.getSample(ch,n)*gate*level);}}
    bool acceptsMidi()const override{return false;}bool producesMidi()const override{return false;}double getTailLengthSeconds()const override{return 0;}
    bool hasEditor()const override{return true;}juce::AudioProcessorEditor* createEditor()override{return new juce::GenericAudioProcessorEditor(*this);}
    int getNumPrograms()override{return 1;}int getCurrentProgram()override{return 0;}void setCurrentProgram(int)override{}const juce::String getProgramName(int)override{return "Default";}void changeProgramName(int,const juce::String&)override{}
    void getStateInformation(juce::MemoryBlock& data)override{juce::MemoryOutputStream out(data,false);out.writeFloat(threshold->getValue());out.writeFloat(gain->getValue());}
    void setStateInformation(const void* data,int n)override{if(n>=8){juce::MemoryInputStream in(data,(size_t)n,false);threshold->setValueNotifyingHost(in.readFloat());gain->setValueNotifyingHost(in.readFloat());}}
};
std::unique_ptr<juce::AudioPluginInstance> makeTestFx(){return std::make_unique<GateFx>();}
}
